import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_gemm_mult_leakyrelu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    const int B,
    const int I,
    const int O,
    const float multiplier,
    const float negative_slope)
{
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < B && col < O)
    {
        float val = 0.0f;
        for (int k = 0; k < I; ++k) {
            val += input[row * I + k] * weight[col * I + k];
        }
        val += bias[col];
        val *= multiplier;
        if (val < 0.0f) {
            val *= negative_slope;
        }
        out[row * O + col] = val;
    }
}

torch::Tensor fused_gemm_mult_leakyrelu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float multiplier,
    float negative_slope)
{
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    TORCH_CHECK(weight.dim() == 2, "Weight must be 2D");
    TORCH_CHECK(bias.dim() == 1, "Bias must be 1D");

    const auto B = input.size(0);
    const auto I = input.size(1);
    const auto O = weight.size(0);

    auto out = torch::empty({B, O}, input.options());

    const int block_x = 16;
    const int block_y = 16;
    dim3 block(block_x, block_y);
    dim3 grid((O + block_x - 1) / block_x, (B + block_y - 1) / block_y);

    fused_gemm_mult_leakyrelu_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, I, O,
        multiplier, negative_slope
    );

    return out;
}
""".strip()

fused_cpp_source = """
torch::Tensor fused_gemm_mult_leakyrelu_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float multiplier,
    float negative_slope
);
"""

fused_matmul_mult_leakyrelu = load_inline(
    name="fused_matmul_mult_leakyrelu",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_gemm_mult_leakyrelu_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, multiplier, negative_slope):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))
        self.multiplier = multiplier
        self.negative_slope = negative_slope

    def forward(self, x):
        return fused_matmul_mult_leakyrelu.fused_gemm_mult_leakyrelu_cuda(
            x,
            self.weight,
            self.bias,
            self.multiplier,
            self.negative_slope
        )
